package com.car.autoverdict.licenses

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.text.Collator
import java.util.Locale

/**
 * Open-source notices generated by scripts/oss-notices (spec 7.3). Two raw resources:
 * `oss_notices.json` ([OssNotices]) and `oss_google_notices.json` ([OssGoogleNotices]).
 */
@Serializable
data class OssNotices(
    val schemaVersion: Int,
    val source: String? = null,
    val licenses: List<OssLicense>,
    val libraries: List<OssLibrary>,
)

/** Either [text] or [url] is set; Google SDK terms are linked, not embedded (spec 2). */
@Serializable
data class OssLicense(
    val id: String,
    val name: String,
    val text: String? = null,
    val url: String? = null,
)

/** One list row: a group of artifacts under one license (e.g. "Jetpack Compose"). */
@Serializable
data class OssLibrary(
    val id: String,
    val name: String,
    val licenseId: String,
    val artifacts: List<String>,
)

/** Notices bundled inside the Play services / UMP AARs; [texts] is keyed by a text hash. */
@Serializable
data class OssGoogleNotices(
    val schemaVersion: Int,
    val texts: Map<String, String>,
    val components: List<OssComponent>,
)

@Serializable
data class OssComponent(
    val name: String,
    val textId: String,
)

/** A license section on the list screen; [isGoogleTerms] titles it "Google 약관". */
data class OssLicenseSection(
    val license: OssLicense,
    val libraries: List<OssLibrary>,
    val isGoogleTerms: Boolean,
)

/** Everything the detail screen shows for one [OssCatalog.detail] id. */
data class OssDetail(
    val title: String,
    /** Null for Google-bundled components, whose notice text names its own license. */
    val licenseName: String?,
    val artifacts: List<String>,
    val text: String?,
    val url: String?,
    val isFont: Boolean,
    val isGoogleBundled: Boolean,
)

/** Both notice files, with the list grouping and detail lookup the screens need. */
class OssCatalog(
    val notices: OssNotices,
    val google: OssGoogleNotices,
) {
    private val licensesById = notices.licenses.associateBy { it.id }

    /** By library count (desc), then name; Google terms always last (spec 7.4). */
    val sections: List<OssLicenseSection> = notices.libraries
        .groupBy { it.licenseId }
        .mapNotNull { (licenseId, libraries) ->
            val license = licensesById[licenseId] ?: return@mapNotNull null
            OssLicenseSection(
                license = license,
                libraries = libraries.sortedWith(compareBy(nameCollator) { it.name }),
                isGoogleTerms = licenseId == GOOGLE_SDK_LICENSE_ID,
            )
        }
        .sortedWith(
            compareBy<OssLicenseSection> { it.isGoogleTerms }
                .thenByDescending { it.libraries.size }
                .thenBy(nameCollator) { it.license.name },
        )

    /** Components bundled inside Google AARs, by name; only those whose text is present. */
    val googleComponents: List<OssComponent> = google.components
        .filter { it.textId in google.texts }
        .sortedWith(compareBy(nameCollator) { it.name })

    /** Resolves a [libraryDetailId] / [googleDetailId]; null when the data no longer has it. */
    fun detail(id: String): OssDetail? = when {
        id.startsWith(LIBRARY_PREFIX) -> {
            val library = notices.libraries.firstOrNull { it.id == id.removePrefix(LIBRARY_PREFIX) }
            val license = library?.let { licensesById[it.licenseId] }
            if (library == null || license == null) {
                null
            } else {
                OssDetail(
                    title = library.name,
                    licenseName = license.name,
                    artifacts = library.artifacts,
                    text = license.text,
                    url = license.url,
                    isFont = isFont(library),
                    isGoogleBundled = false,
                )
            }
        }
        id.startsWith(GOOGLE_PREFIX) -> {
            val component = google.components.firstOrNull { it.name == id.removePrefix(GOOGLE_PREFIX) }
            val text = component?.let { google.texts[it.textId] }
            if (component == null || text == null) {
                null
            } else {
                OssDetail(
                    title = component.name,
                    licenseName = null,
                    artifacts = emptyList(),
                    text = text,
                    url = null,
                    isFont = false,
                    isGoogleBundled = true,
                )
            }
        }
        else -> null
    }

    companion object {
        const val GOOGLE_SDK_LICENSE_ID = "google-android-sdk"
        private const val FONT_LICENSE_ID = "ofl-1.1"
        private const val LIBRARY_PREFIX = "lib:"
        private const val GOOGLE_PREFIX = "google:"

        private val json = Json { ignoreUnknownKeys = true }

        // Korean collation keeps "android_build" next to "Android SDK" and Hangul after Latin.
        private val nameCollator: Comparator<String> =
            Collator.getInstance(Locale.KOREAN).apply { strength = Collator.SECONDARY }
                .let { collator -> Comparator { a, b -> collator.compare(a, b) } }

        fun parse(noticesJson: String, googleJson: String): OssCatalog = OssCatalog(
            notices = json.decodeFromString(OssNotices.serializer(), noticesJson),
            google = json.decodeFromString(OssGoogleNotices.serializer(), googleJson),
        )

        fun libraryDetailId(library: OssLibrary): String = LIBRARY_PREFIX + library.id

        fun googleDetailId(component: OssComponent): String = GOOGLE_PREFIX + component.name

        /** The bundled font is listed as "폰트" rather than a module count. */
        fun isFont(library: OssLibrary): Boolean = library.licenseId == FONT_LICENSE_ID

        /**
         * Splits a notice into blank-line separated paragraphs so a long text (up to ~110KB)
         * renders lazily instead of as one huge Text.
         */
        fun paragraphs(text: String): List<String> =
            text.split(PARAGRAPH_BREAK).map { it.trimEnd() }.filter { it.isNotBlank() }.map { it.trimStart('\n') }

        private val PARAGRAPH_BREAK = Regex("\\n(?:[ \\t]*\\n)+")
    }
}
